mapper.select:
SELECT COUNT(*) AS totalCount, COALESCE(SUM(CASE WHEN er.status = 'DRAFT' THEN 1 ELSE 0 END), 0) AS draftCount, COALESCE(SUM(CASE WHEN er.status = 'APPROVING' THEN 1 ELSE 0 END), 0) AS approvingCount, COALESCE(SUM(CASE WHEN er.status = 'FINANCE_REVIEW' THEN 1 ELSE 0 END), 0) AS financeReviewCount, COALESCE(SUM(CASE WHEN er.status = 'REJECTED' THEN 1 ELSE 0 END), 0) AS rejectedCount, COALESCE(SUM(CASE WHEN er.status = 'PENDING_PAYMENT' THEN 1 ELSE 0 END), 0) AS pendingPaymentCount, COALESCE(SUM(CASE WHEN er.status = 'COMPLETED' THEN 1 ELSE 0 END), 0) AS completedCount, COALESCE(SUM(CASE WHEN er.status = 'WITHDRAWN' THEN 1 ELSE 0 END), 0) AS withdrawnCount, COALESCE(SUM(er.total_amount), 0) AS totalAmount FROM expense_report er WHERE er.deleted = 0
AND er.created_at >= #{startTime}
AND er.created_at <= #{endTime}
AND EXISTS ( SELECT 1 FROM approval_task task WHERE task.report_id = er.id AND task.approver_id = #{userId} )
AND er.applicant_id = #{userId}

SELECT er.id, er.report_no, er.applicant_id, er.department_id,
       er.title, er.total_amount, er.currency, er.status,
       er.approval_round, er.submitted_at, er.completed_at,
       er.version, er.created_at, er.updated_at
FROM expense_report er
WHERE er.deleted = 0

    AND (er.report_no LIKE CONCAT('%', #{keyword}, '%')
         OR er.title LIKE CONCAT('%', #{keyword}, '%'))


    AND er.status = #{status}


    AND er.created_at >= #{startTime}


    AND er.created_at <= #{endTime}





        AND EXISTS (
            SELECT 1 FROM approval_task task
            WHERE task.report_id = er.id
              AND task.approver_id = #{userId}
        )


        AND er.applicant_id = #{userId}


ORDER BY er.created_at DESC
